/*flags=*/0, /*opts=*/0x200000000240, /*chdir=*/1, /*size=*/0x471c,
/*img=*/0x20000000d5c0);
//  creat arguments: [
//    file: ptr[in, buffer] {
//      buffer: {2e 2f 62 75 73 00} (length 0x6)
//    }
//    mode: open_mode = 0x0 (8 bytes)
